Вопрос: Сколько допустимых строк отмечено правилом IQR по доле занятости внутри каждой пары месяц/парковка? Они сохраняются в P1.

function.arguments:
{"code":"from fractions import Fraction as F
p1=(df.parkingSpaces>0)&(df.freeParking>=0)&(df.freeParking<=df.parkingSpaces)
x=df[p1].copy(); x['month']=pd.to_datetime(x.dateServ).dt.to_period('M'); x['occ']=1-x.freeParking/x.parkingSpaces
counts=[0,0,0]; differences=[]
for k,s in x.groupby(['month','idParking']):
    r=[F(int(t)-int(f),int(t)) for f,t in zip(s.freeParking,s.parkingSpaces)]; v=sorted(r)
    def q(p):
        h=(len(v)-1)*p; i=h.numerator//h.denominator
        return v[i]+(h-i)*(v[min(i+1,len(v)-1)]-v[i])
    a,b=q(F(1,4)),q(F(3,4)); lo,hi=a-F(3,2)*(b-a),b+F(3,2)*(b-a)
    exact=[z<lo or z>hi for z in r]; counts[0]+=sum(exact)
    for j,y in enumerate([s.occ,(s.parkingSpaces-s.freeParking)/s.parkingSpaces],1):
        aa,bb=y.quantile([.25,.75]); z=(y<aa-1.5*(bb-aa))|(y>bb+1.5*(bb-aa)); counts[j]+=z.sum()
        if list(z)!=exact: differences.append((k,j,sum(exact),z.sum(),[(str(vv),str(lo),str(hi)) for vv,c,d in zip(r,exact,z) if c!=d][:10]))
print(counts); print(differences)
print(df.loc[~p1,'freeParking'].value_counts().head(10))"}

